import { email, attio, slack } from adapters
import { acme_main, acme_workspace } from credentials

inbox = email()
crm   = attio(credentials: acme_main)
team  = slack(credentials: acme_workspace)

movement log_dealflow(msg: <inbox-[:message]->>) {

  deals = extract from [msg.`text`] {
    digest: "a one-line summary of the dealflow message"
    node company: "each company seeking investment in this message" {
      name: "the company's name"
      stage: "the funding stage, e.g. Seed"
    }
  }

  write team-[:messages]-> {
    channel: "#dealflow"
    text:    deals.`digest`
  }

  deals-[c:company]-> {
    write crm-[:companies]-> {
      unique by (`name`)
      name:    c.`name`
      summary: c.`stage`
    }
  }
}

import { email, attio, slack } from adapters
import { acme_main, acme_workspace } from credentials

inbox = email()
crm   = attio(credentials: acme_main)
team  = slack(credentials: acme_workspace)

movement race_sync(msg: <inbox-[:message]->>) {
  r = await race([
    () => {
      made = write crm-[:companies]-> {
        unique by (`domains`)
        name:    msg.`subject`
        domains: [msg.`text`]
      }
      return made.externalId
    },
    () => { return true },
  ])
  write team-[:messages]-> {
    channel: "#c"
    text:    "id=${AT(r, 0)}"
  }
  write team-[:messages]-> {
    channel: "#c2"
    text:    "flag=${AT(r, 1)}"
  }
}

