movement race_tie(msg: <inbox-[:message]->>) {
  r = await race([
    () => { one = write crm-[:companies]-> { name: "A" }; return one.externalId },
    () => { two = write crm-[:companies]-> { name: "B" }; return two.externalId },
  ])
  write team-[:messages]-> {
    channel: "#one"
    text:    "one=${AT(r, 0)}"
  }
  write team-[:messages]-> {
    channel: "#two"
    text:    "two=${AT(r, 1)}"
  }
}

