        }
      }
    }
  }

  deals-[c:company]-> {
    co = write graph-[:companies]-> {
      unique by (`name`)
      name: c.`name`
    }

    c-[r:round]-> {
      fr = write co-[:rounds]-> {
        unique by (co AND `stage`)
        stage: r.`stage`
      }

      r-[i:investor]-> {
        write fr-[:participants]-> {
          unique by (fr AND `investor_name`)
          investor_name: i.`name`
          lead ?:        i.`lead`
        }
      }
    }
  }
}

