  subject: <text>
  node Attachments {
    Name: <text | null>
    File: <file>
    node Versions {
      Label: <text>
    }
  }
}

node Detailed {
  note: <text | null>
  node part {
    label: <text>
  }
}

node Note {
  text: <text>
  node tag {
    label: <text>
  }
}

movement takes_message(msg: <Message>) {
}

movement from_email(m: <inbox-[:message]->>) {
  return graph<Message> {
    text: m.Body,
    attachment: m-[a:Attachments]-> { name: a.Name, type: a.Type, file: a.`File` },
  }
}

movement under_test(e: <inbox-[:message]->>) {
  g = graph { files: e-[:Attachments]-> }
  g-[f:files]-> {
    n = f.Type
  }
}

