inbox = email(credentials: dealflow_inbox)
crm   = attio(credentials: acme_main)
movement m(msg: <inbox-[:message]->>) {
  co = match crm-[:companies]-> { unique by (`name`), name: msg.`subject` }
  await sleep(30s)
  if co != null {
    write co-[:notes]-> { body: co.`stage` }
  }
}

