movement notify_company_change(evt: <crm-[:`Webhook Event`]->>) {
  channel = ONLY(chat-[ch:Channels WHERE `Name` == "auto-alerts"]->)


  if evt IS <crm-[:`Webhook Event` WHERE `action` == "record.created"]->> {
    evt-[co:Companies]-> {
      domain      = ONLY(co.Domains)
