  return node { title: m.`Subject` }
}

movement maybe(m: <inbox-[:message]->>) {
  return node { s: m.`Snoozed` }
}

movement effects_only(m: <inbox-[:message]->>) {
  t = m.`Subject`
}

movement main(e: <inbox-[:message]->>) {
  bad = counts(m: e)
  takes_doc(d: bad)
}

