import { email, attio } from adapters
import { acme_main } from credentials

inbox = email()

node Company {
  name: <text>
  summary: <text>
}

node Entry {
  name: <text>
  node founder {
    first: <text>
    last: <text>
  }
}

node OrderedEntry {
  name: <text>
  node founder {
    first: <text>
    last: <text>
  } order by arrival
}
movement intake(msg: <inbox-[:message]->>) {
  crm = attio(credentials: acme_main)
  deduped = node { companies: <Company> order by arrival }
  write deduped-[:companies]-> { unique by (`name`)
    name: "Acme"
  }
  write deduped-[:companies]-> { unique by (`name`)
    name: "Beta"
  }
  write deduped-[:companies]-> { unique by (`name`)
    name: "Gamma"
  }
  joined = JOIN(deduped-[c:companies]->.`name`, ", ")
  write crm-[:companies]-> { name: joined }
}

