sys = crm()

node Company {
  name: <text>
  thesis: <text | null>
  website: <text | null>
}

movement m(msg: <inbox-[:message]->>) {
  deduped = node { companies: <Company> order by arrival }
  h = write deduped-[:companies]-> { unique by (FUZZY name)
    name: "Acme"
  }
  MAP(FILTER(deduped-[:companies]->, (e) => e.name == "Acme"), (e) => {
    write e { thesis: "x" }
  })
}

