  if lead != null {
    link c -[:Owner]-> lead
  }
  pick = IF facts.amount > 1 THEN facts.name ELSE "none" END
  a = write questions-[:Check]-> { prompt: "approve this deal?" }
  answer = await FIRST(a-[:Response]->)
  amount = COALESCE(facts.amount, 0)
  timing = race(() => { await sleep(2d) }, () => { return TRUE })
  if amount > 1000 {
    write d { Stage: "big" }
  } else {
    write d { Stage: "small" }
  }
  note_owner(co: c)
}

